const projetos=[{titulo:"Arrecadação de Alimentos e Água",status:"Em andamento",descricao:"Realizamos campanhas para arrecadar alimentos e água potável e destiná-los a famílias afetadas por desastres naturais."},{titulo:"Doações Financeiras",status:"",descricao:"As doações financeiras ajudam o Projeto Reconstruir a atender necessidades urgentes das comunidades afetadas."},{titulo:"Doação de Roupas e Outros Itens",status:"",descricao:"Recebemos roupas, calçados, cobertores, produtos de higiene, materiais de limpeza e quaisquer outros itens que possam ser úteis às famílias."},{titulo:"Materiais para Reconstrução",status:"",descricao:"Arrecadamos ferramentas e materiais que possam contribuir para a recuperação de moradias e espaços afetados."},{titulo:"Ações com Voluntários",status:"",descricao:"Organizamos ações voluntárias para distribuir doações, apoiar comunidades afetadas e colaborar com as famílias."}];export function gerarProjetos(){const a=document.querySelector("#lista-projetos");a&&(a.innerHTML=projetos.map(function(a){return`\n            <section>\n                <h2>${a.titulo}</h2>\n                ${a.status?`<span class="badge">${a.status}</span>`:""}\n                <p>${a.descricao}</p>\n            </section>\n        `}).join(""))}